                    $installButton.Enabled = $true
                    $cancelButton.Enabled = $true
                }
            } else {
                [System.Windows.Forms.MessageBox]::Show("Failed to install agent files. Please check the log file at: $LogFile", "Installation Failed", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
