            [System.Windows.Forms.MessageBox]::Show("Failed to register with server. Please check your token and network connection.", "Registration Failed", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
            $installButton.Enabled = $true
            $cancelButton.Enabled = $true
            $progressBar.Value = 0
            $statusLabel.Text = "Ready to install"
        }
    })

    # Show the form
    $result = $form.ShowDialog()
    return $result
}

function Register-WithServer {
    param(
        [hashtable]$SystemInfo,
        [string]$Token,
        [string]$CompanyId,
        [string]$MSPId,
        [string]$ServerUrl
    )
    
    $registrationData = @{
        action = "register_agent"
        hostname = $SystemInfo.hostname
        ip_address = $SystemInfo.ip_address
        os_info = $SystemInfo.os_info
        device_type = $SystemInfo.device_type
        agent_version = $SystemInfo.agent_version
        client_id = $CompanyId
        msp_id = $MSPId
        system_info = $SystemInfo
    }
    
    try {
        $headers = @{
            "Content-Type" = "application/json"
            "Authorization" = "Bearer $Token"
        }
        
        $response = Invoke-RestMethod -Uri "$ServerUrl/functions/v1/rmm-agent" -Method Post -Body ($registrationData | ConvertTo-Json -Depth 5) -Headers $headers -TimeoutSec 30
        
        if ($response.success) {
            Write-Log "Agent registered successfully. Device ID: $($response.device_id)"
            return $response.device_id
        } else {
            Write-Log "Registration failed: $($response.error)"
            return $null
        }
    } catch {
        Write-Log "Registration error: $($_.Exception.Message)"
        return $null
    }
}

function Install-AgentFiles {
    param(
        [string]$DeviceId,
        [string]$Token,
        [string]$CompanyId,
        [string]$MSPId,
        [string]$ServerUrl,
        [hashtable]$SystemInfo
    )
    
    try {
        # Create installation directory
        if (-not (Test-Path $InstallPath)) {
            New-Item -ItemType Directory -Path $InstallPath -Force | Out-Null
        }
        
        # Create configuration file
        $config = @{
            server_url = $ServerUrl
            agent_token = $Token
            company_id = $CompanyId
            msp_id = $MSPId
            device_id = $DeviceId
            heartbeat_interval = 30
            command_check_interval = 10
            install_date = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ssZ")
            version = "2.1.0-gui"
            system_info = $SystemInfo
        }
        
        $config | ConvertTo-Json -Depth 4 | Out-File -FilePath $ConfigFile -Encoding UTF8
        
        # Create the service script (same as before but optimized)
        $ServiceScriptContent = @"
# Ultrium RMM Agent Service - GUI Version
`$ConfigPath = "$ConfigFile"
`$LogPath = "$LogFile"

function Write-AgentLog {
    param([string]`$Message)
    `$timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    try {
        "`$timestamp - `$Message" | Out-File -FilePath `$LogPath -Append
    } catch {}
}

function Load-Config {
    try {
        if (Test-Path `$ConfigPath) {
            return Get-Content `$ConfigPath | ConvertFrom-Json
        }
    } catch {
        Write-AgentLog "Error loading config: `$(`$_.Exception.Message)"
    }
    return `$null
}

function Send-Heartbeat {
    param([object]`$Config)
    
    try {
        `$cpu = Get-WmiObject -Class Win32_Processor | Measure-Object -Property LoadPercentage -Average
        `$memory = Get-WmiObject -Class Win32_OperatingSystem
        `$disk = Get-WmiObject -Class Win32_LogicalDisk -Filter "DriveType=3" | Select-Object -First 1
        
        `$metrics = @{
            cpu_usage = `$cpu.Average
            memory_usage = [math]::Round(((`$memory.TotalVisibleMemorySize - `$memory.FreePhysicalMemory) / `$memory.TotalVisibleMemorySize) * 100, 2)
            disk_usage = if (`$disk) { [math]::Round(((`$disk.Size - `$disk.FreeSpace) / `$disk.Size) * 100, 2) } else { 0 }
            timestamp = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ssZ")
        }
        
        `$heartbeatData = @{
            action = "heartbeat"
            device_id = `$Config.device_id
            metrics = `$metrics
        }
        
        `$headers = @{
            "Content-Type" = "application/json"
            "Authorization" = "Bearer `$(`$Config.agent_token)"
        }
        
        Invoke-RestMethod -Uri "`$(`$Config.server_url)/functions/v1/rmm-agent" -Method Post -Body (`$heartbeatData | ConvertTo-Json -Depth 3) -Headers `$headers -TimeoutSec 30 | Out-Null
        Write-AgentLog "Heartbeat sent successfully"
        
    } catch {
        Write-AgentLog "Heartbeat failed: `$(`$_.Exception.Message)"
    }
}

function Check-Commands {
    param([object]`$Config)
    
    try {
        `$commandData = @{
            action = "get_commands"
            device_id = `$Config.device_id
        }
        
        `$headers = @{
            "Content-Type" = "application/json"
            "Authorization" = "Bearer `$(`$Config.agent_token)"
        }
        
        `$response = Invoke-RestMethod -Uri "`$(`$Config.server_url)/functions/v1/rmm-command" -Method Post -Body (`$commandData | ConvertTo-Json) -Headers `$headers -TimeoutSec 30
        
        if (`$response.success -and `$response.commands) {
            foreach (`$command in `$response.commands) {
                Write-AgentLog "Executing command: `$(`$command.command)"
                
                `$result = @{
                    action = "command_result"
                    command_id = `$command.id
                    success = `$false
                    output = ""
                    error = ""
                }
                
                try {
                    switch (`$command.command_type) {
                        "powershell" {
                            `$output = Invoke-Expression `$command.command 2>&1
                            `$result.success = `$true
                            `$result.output = `$output -join "`n"
                        }
                        "cmd" {
                            `$output = cmd /c `$command.command 2>&1
                            `$result.success = `$true
                            `$result.output = `$output -join "`n"
                        }
                        default {
                            `$result.error = "Unknown command type"
                        }
                    }
                } catch {
                    `$result.error = `$_.Exception.Message
                }
                
                # Send result back
                try {
                    Invoke-RestMethod -Uri "`$(`$Config.server_url)/functions/v1/rmm-command" -Method Post -Body (`$result | ConvertTo-Json -Depth 3) -Headers `$headers -TimeoutSec 30 | Out-Null
                    Write-AgentLog "Command result sent for: `$(`$command.id)"
                } catch {
                    Write-AgentLog "Failed to send command result: `$(`$_.Exception.Message)"
                }
            }
        }
        
    } catch {
        Write-AgentLog "Error checking commands: `$(`$_.Exception.Message)"
    }
}

# Main service loop
Write-AgentLog "Starting Ultrium RMM Agent v2.1 GUI..."

`$config = Load-Config
if (-not `$config) {
    Write-AgentLog "ERROR: Could not load configuration"
    exit 1
}

Write-AgentLog "Loaded configuration for device: `$(`$config.device_id)"

# Main loop
while (`$true) {
    try {
        Send-Heartbeat -Config `$config
        Check-Commands -Config `$config
        
        Start-Sleep -Seconds `$config.heartbeat_interval
        
    } catch {
        Write-AgentLog "ERROR in main loop: `$(`$_.Exception.Message)"
        Start-Sleep -Seconds 60
    }
}
"@

        $ServiceScriptPath = "$InstallPath\service.ps1"
        $ServiceScriptContent | Out-File -FilePath $ServiceScriptPath -Encoding UTF8
        
        Write-Log "Agent files created successfully"
        return $true
        
    } catch {
        Write-Log "Error creating agent files: $($_.Exception.Message)"
        return $false
    }
}

function Create-AgentService {
    try {
        $ServiceScriptPath = "$InstallPath\service.ps1"
        $servicePath = "powershell.exe -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$ServiceScriptPath`""
        
        # Stop and remove existing service if it exists
        if (Get-Service -Name $ServiceName -ErrorAction SilentlyContinue) {
            Stop-Service -Name $ServiceName -Force -ErrorAction SilentlyContinue
            sc.exe delete $ServiceName | Out-Null
            Start-Sleep -Seconds 3
        }
        
        # Create new service
        New-Service -Name $ServiceName -DisplayName $ServiceDisplayName -Description $ServiceDescription -BinaryPathName $servicePath -StartupType Automatic | Out-Null
        
        # Start the service
        Start-Service -Name $ServiceName
        
        Write-Log "Service created and started successfully"
        return $true
        
    } catch {
        Write-Log "Error creating service: $($_.Exception.Message)"
        return $false
    }
}

function Show-SystemTrayIcon {
    try {
        # Create system tray icon
        Add-Type -AssemblyName System.Windows.Forms
        
        $notifyIcon = New-Object System.Windows.Forms.NotifyIcon
        
        # Set icon from base64
        try {
            $iconBytes = [Convert]::FromBase64String($UltriumIconBase64)
            $ms = New-Object System.IO.MemoryStream($iconBytes, 0, $iconBytes.Length)
            $notifyIcon.Icon = [System.Drawing.Icon]::FromHandle(([System.Drawing.Bitmap]::new($ms)).GetHicon())
        } catch {
            # Use default icon if custom icon fails
            $notifyIcon.Icon = [System.Drawing.SystemIcons]::Information
        }
        
        $notifyIcon.BalloonTipTitle = "Ultrium RMM Agent"
        $notifyIcon.BalloonTipText = "Agent installed successfully and is now monitoring this device."
        $notifyIcon.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::Info
        $notifyIcon.Text = "Ultrium RMM Agent - Monitoring Active"
        $notifyIcon.Visible = $true
        
        # Show balloon tip
        $notifyIcon.ShowBalloonTip(5000)
        
        # Create context menu
        $contextMenu = New-Object System.Windows.Forms.ContextMenuStrip
        
        $statusItem = New-Object System.Windows.Forms.ToolStripMenuItem
        $statusItem.Text = "Agent Status: Running"
        $statusItem.Enabled = $false
        
        $separator1 = New-Object System.Windows.Forms.ToolStripSeparator
        
        $openLogsItem = New-Object System.Windows.Forms.ToolStripMenuItem
        $openLogsItem.Text = "View Logs"
        $openLogsItem.Add_Click({
            if (Test-Path $LogFile) {
                Start-Process notepad.exe $LogFile
            }
        })
        
        $configItem = New-Object System.Windows.Forms.ToolStripMenuItem
        $configItem.Text = "View Configuration"
        $configItem.Add_Click({
            if (Test-Path $ConfigFile) {
                Start-Process notepad.exe $ConfigFile
            }
        })
        
        $separator2 = New-Object System.Windows.Forms.ToolStripSeparator
        
        $exitItem = New-Object System.Windows.Forms.ToolStripMenuItem
        $exitItem.Text = "Hide Icon"
        $exitItem.Add_Click({
            $notifyIcon.Visible = $false
            $notifyIcon.Dispose()
        })
        
        $contextMenu.Items.AddRange(@($statusItem, $separator1, $openLogsItem, $configItem, $separator2, $exitItem))
        $notifyIcon.ContextMenuStrip = $contextMenu
        
        # Keep icon active for 30 seconds, then hide
        $timer = New-Object System.Windows.Forms.Timer
        $timer.Interval = 30000
        $timer.Add_Tick({
            $notifyIcon.Visible = $false
            $notifyIcon.Dispose()
            $timer.Stop()
            $timer.Dispose()
        })
        $timer.Start()
        
    } catch {
        Write-Log "Error creating system tray icon: $($_.Exception.Message)"
    }
}

