function Uninstall-Agent {
    if (-not (Test-Administrator)) {
        [System.Windows.Forms.MessageBox]::Show("This script must be run as Administrator to uninstall the service.", "Administrator Required", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        exit 1
    }

    $result = Show-UninstallGUI
    if ($result -eq [System.Windows.Forms.DialogResult]::OK) {
        try {
            Write-Log "Uninstalling Ultrium RMM Agent..."
            
            # Stop and remove service
            if (Get-Service -Name $ServiceName -ErrorAction SilentlyContinue) {
                Stop-Service -Name $ServiceName -Force -ErrorAction SilentlyContinue
                sc.exe delete $ServiceName | Out-Null
                Write-Log "Service removed successfully"
            }
            
            # Remove installation directory
            if (Test-Path $InstallPath) {
                Remove-Item -Path $InstallPath -Recurse -Force
                Write-Log "Installation directory removed"
            }
            
            [System.Windows.Forms.MessageBox]::Show("Ultrium RMM Agent uninstalled successfully!", "Uninstall Complete", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
            
        } catch {
            Write-Log "ERROR during uninstall: $($_.Exception.Message)"
            [System.Windows.Forms.MessageBox]::Show("Error during uninstall: $($_.Exception.Message)", "Uninstall Failed", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    }
}

function Show-StatusGUI {
    $form = New-Object System.Windows.Forms.Form
    $form.Text = "Ultrium RMM Agent - Status"
    $form.Size = New-Object System.Drawing.Size(500, 350)
    $form.StartPosition = "CenterScreen"
    $form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $form.MaximizeBox = $false

    $service = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    
    $statusLabel = New-Object System.Windows.Forms.Label
    if ($service) {
        $statusText = "Service Status: $($service.Status)"
        $statusColor = if ($service.Status -eq "Running") { [System.Drawing.Color]::Green } else { [System.Drawing.Color]::Red }
    } else {
        $statusText = "Service Status: Not Installed"
        $statusColor = [System.Drawing.Color]::Red
    }
    
    $statusLabel.Text = $statusText
    $statusLabel.Location = New-Object System.Drawing.Point(20, 20)
    $statusLabel.Size = New-Object System.Drawing.Size(400, 30)
    $statusLabel.Font = New-Object System.Drawing.Font("Segoe UI", 12, [System.Drawing.FontStyle]::Bold)
    $statusLabel.ForeColor = $statusColor

    $detailsText = New-Object System.Windows.Forms.TextBox
    $detailsText.Location = New-Object System.Drawing.Point(20, 60)
    $detailsText.Size = New-Object System.Drawing.Size(440, 200)
    $detailsText.Multiline = $true
    $detailsText.ScrollBars = [System.Windows.Forms.ScrollBars]::Vertical
    $detailsText.ReadOnly = $true

    $details = ""
    if (Test-Path $ConfigFile) {
        $config = Get-Content $ConfigFile | ConvertFrom-Json
        $details += "Configuration:`r`n"
        $details += "  Device ID: $($config.device_id)`r`n"
        $details += "  Server URL: $($config.server_url)`r`n"
        $details += "  Company ID: $($config.company_id)`r`n"
        $details += "  Version: $($config.version)`r`n"
        $details += "  Install Date: $($config.install_date)`r`n`r`n"
    }

    if (Test-Path $LogFile) {
        $details += "Recent Log Entries:`r`n"
        $logEntries = Get-Content $LogFile -Tail 10
        foreach ($entry in $logEntries) {
            $details += "  $entry`r`n"
        }
    }

    $detailsText.Text = $details

    $closeButton = New-Object System.Windows.Forms.Button
    $closeButton.Text = "Close"
    $closeButton.Location = New-Object System.Drawing.Point(390, 280)
    $closeButton.Size = New-Object System.Drawing.Size(70, 30)
    $closeButton.DialogResult = [System.Windows.Forms.DialogResult]::OK

    $form.Controls.AddRange(@($statusLabel, $detailsText, $closeButton))
    $form.ShowDialog() | Out-Null
}

# Main execution
try {
    if (-not $Silent) {
        if ($args.Length -eq 0) {
            # No arguments provided, show installation GUI
            $result = Show-InstallationGUI
        } elseif ($args[0] -eq "-Uninstall") {
            Uninstall-Agent
        } elseif ($args[0] -eq "-Status") {
            Show-StatusGUI
        } else {
            # Command line installation
            if (-not (Test-Administrator)) {
                [System.Windows.Forms.MessageBox]::Show("This script must be run as Administrator.", "Administrator Required", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
                exit 1
            }
            
            if ([string]::IsNullOrWhiteSpace($AgentToken)) {
                Write-Error "AgentToken is required for installation."
                Write-Host "Usage: .\UltriumRMMAgent-GUI-Installer.ps1 -AgentToken 'your-token' -CompanyId 'your-company-id'"
                exit 1
            }
            
            # Silent installation
            $systemInfo = Get-SystemInfo
            $deviceId = Register-WithServer -SystemInfo $systemInfo -Token $AgentToken -CompanyId $CompanyId -MSPId $MSPId -ServerUrl $ServerUrl
            
            if ($deviceId) {
                $success = Install-AgentFiles -DeviceId $deviceId -Token $AgentToken -CompanyId $CompanyId -MSPId $MSPId -ServerUrl $ServerUrl -SystemInfo $systemInfo
                if ($success) {
                    $serviceSuccess = Create-AgentService
                    if ($serviceSuccess) {
                        Write-Host "Ultrium RMM Agent installed successfully!" -ForegroundColor Green
                        Write-Host "Device ID: $deviceId" -ForegroundColor Cyan
                        Show-SystemTrayIcon
                    }
                }
            }
        }
    } else {
        # Silent mode installation
        Write-Host "Running in silent mode..."
        # Implementation for silent installation
    }
} catch {
    Write-Error "An error occurred: $($_.Exception.Message)"
    Write-Log "ERROR: $($_.Exception.Message)"
    exit 1
}